steps.script:
var main = tree.current_scene
for i in range(main.army_options.size()):
	if str(main.army_options[i].id) == "WPW3_E2E_Custodes":
		return i
return -1

var raw = ArmyListManager.cloud_army_cache.get("WPW3_E2E_Custodes", {})
var src := str(raw.get("faction", {}).get("data_source", ""))
print("[w3 builder] cloud army data_source=", src)
return src.begins_with("40kdc-data 1.4.5") and src.contains("Wahapedia 11e codex import")

for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) == 1 and str(u.meta.get("name", "")) == "Shield-Captain":
		var s = u.meta.stats
		var names := []
		for a in u.meta.get("abilities", []):
			names.append(str(a.get("name", "")) if a is Dictionary else str(a))
		GameState.state.meta["_w3_sc"] = uid
		print("[w3 builder] ", uid, " stats=", s, " model W=", u.models[0].get("wounds"), " pts=", u.meta.get("points"), " wargear=", u.meta.get("wargear"), " abilities=", names)
		return int(s.wounds) == 8 and int(u.models[0].wounds) == 8 and int(s.toughness) == 7 and int(s.move) == 8 and int(u.meta.points) == 205 and names.has("Praesidium Shield") and bool(u.meta.get("is_warlord", false))
return "no Shield-Captain"

for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) == 1 and str(u.meta.get("name", "")) == "Custodian Guard Sodality":
		var ws := []
		for m in u.models:
			ws.append(int(m.wounds))
		print("[w3 builder] ", uid, " models W=", ws, " OC=", u.meta.stats.objective_control, " pts=", u.meta.points)
		return u.models.size() == 3 and ws == [5, 5, 5] and int(u.meta.stats.objective_control) == 3 and int(u.meta.points) == 240
return "no Sodality"

var ds = tree.current_scene.get_node("DatasheetModal")
print("[w3 builder] datasheet stats_text=", ds.stats_text)
return ds.stats_text.contains("W 8") and ds.stats_text.contains("T 7") and ds.stats_text.contains("M 8")
